@using sv_7bc0da4ea6fa4a29a4742751742e42cf.Models

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" value="@Personal.FullName" @onchange="e => UpdateField(Personal with { FullName = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="form-group">
        <label>Email *</label>
        <input type="email" value="@Personal.Email" @onchange="e => UpdateField(Personal with { Email = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" value="@Personal.Phone" @onchange="e => UpdateField(Personal with { Phone = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="form-group">
        <label>Address *</label>
        <input type="text" value="@Personal.Address" @onchange="e => UpdateField(Personal with { Address = (string?)e.Value ?? string.Empty })" />
    </div>

    <div class="step-buttons">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public EventCallback<PersonalInfo> OnPersonalChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task UpdateField(PersonalInfo updated)
    {
        await OnPersonalChanged.InvokeAsync(updated);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Personal.FullName) ||
            string.IsNullOrWhiteSpace(Personal.Email) ||
            string.IsNullOrWhiteSpace(Personal.Phone) ||
            string.IsNullOrWhiteSpace(Personal.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Personal.Email);
            IsValidating = false;

            if (!isValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

