@using sv_7bc0da4ea6fa4a29a4742751742e42cf.Models

<div class="step-content">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <div class="entry-card">
            <h4>Position @(index + 1)</h4>
            <WorkEntryForm Entry="@Entries[index]"
                           CanRemove="@(Entries.Count > 1)"
                           OnEntryChanged="e => UpdateEntry(index, e)"
                           OnRemove="() => RemoveEntry(index)" />
        </div>
    }

    <button class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-buttons">
        <button class="btn-outline" @onclick="() => OnBack.InvokeAsync()">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntry> Entries { get; set; } = default!;
    [Parameter] public EventCallback<List<WorkEntry>> OnEntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private async Task UpdateEntry(int index, WorkEntry updated)
    {
        var list = new List<WorkEntry>(Entries);
        list[index] = updated;
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task RemoveEntry(int index)
    {
        var list = new List<WorkEntry>(Entries);
        list.RemoveAt(index);
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task AddEntry()
    {
        var list = new List<WorkEntry>(Entries)
        {
            new WorkEntry(string.Empty, string.Empty, DateTime.Today, null, string.Empty)
        };
        await OnEntriesChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync();
    }
}

