@page "/apply"
@using sv_7bc0da4ea6fa4a29a4742751742e42cf.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Personal="@personalInfo"
                              OnPersonalChanged="p => personalInfo = p"
                              OnNext="() => NavigateToStep(1)"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnEntriesChanged="e => workEntries = e"
                             OnNext="() => NavigateToStep(2)"
                             OnBack="() => NavigateToStep(0)" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnReferencesChanged="r => references = r"
                            OnNext="() => NavigateToStep(3)"
                            OnBack="() => NavigateToStep(1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnCoverLetterChanged="c => coverLetter = c"
                             OnNext="() => NavigateToStep(4)"
                             OnBack="() => NavigateToStep(2)" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditStep="NavigateToStep"
                        OnBack="() => NavigateToStep(3)"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private PersonalInfo personalInfo = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> workEntries = new() { new(string.Empty, string.Empty, DateTime.Today, null, string.Empty) };
    private List<Reference> references = new() { new(string.Empty, string.Empty, string.Empty, string.Empty) };
    private string coverLetter = string.Empty;

    private void NavigateToStep(int step)
    {
        currentStep = step;
        StateHasChanged();
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            personalInfo,
            new WorkHistory(workEntries),
            references,
            coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    gap: 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    padding: 0 0.5rem;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step.active .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.dimmed .step-circle {
    border-color: #dee2e6;
    background: #f8f9fa;
    color: #adb5bd;
}

.step-label {
    font-size: 0.75rem;
    margin-top: 0.4rem;
    text-align: center;
    white-space: nowrap;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #198754;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 2rem;
}

.step-content h3 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    color: #212529;
}

/* Forms */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.3rem;
    color: #495057;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    box-sizing: border-box;
}

.form-group textarea {
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    font-weight: normal !important;
    margin-top: 0.4rem;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Entry Cards */
.entry-card {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-card h4 {
    margin-top: 0;
    margin-bottom: 1rem;
    color: #495057;
}

/* Buttons */
.step-buttons {
    display: flex;
    gap: 1rem;
    margin-top: 2rem;
    justify-content: flex-end;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
    border: none;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-primary:hover {
    background: #0b5ed7;
}

.btn-primary:disabled {
    background: #6c757d;
    cursor: not-allowed;
}

.btn-outline {
    background: #fff;
    color: #0d6efd;
    border: 1px solid #0d6efd;
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
}

.btn-outline:hover {
    background: #e7f1ff;
}

.btn-secondary {
    background: #fff;
    color: #495057;
    border: 1px solid #ced4da;
    padding: 0.5rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    margin-bottom: 1rem;
}

.btn-secondary:hover {
    background: #e9ecef;
}

.btn-remove {
    background: none;
    color: #dc3545;
    border: 1px solid #dc3545;
    padding: 0.3rem 0.8rem;
    border-radius: 4px;
    font-size: 0.85rem;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-remove:hover {
    background: #dc3545;
    color: #fff;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

/* Character count */
.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.3rem;
}

/* Error message */
.error-message {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    margin-bottom: 1rem;
}

/* Review */
.review-section {
    border-bottom: 1px solid #dee2e6;
    padding-bottom: 1rem;
    margin-bottom: 1rem;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.review-header h4 {
    margin: 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.3rem 1rem;
    margin: 0.5rem 0 0 0;
}

.review-section dt {
    font-weight: 500;
    color: #6c757d;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    margin: 0.5rem 0;
    padding: 0.5rem;
    background: #f8f9fa;
    border-radius: 4px;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
}

.confirmation h4 {
    color: #198754;
    font-size: 1.5rem;
}

